function BeginnerEventDialog:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, true)
        Events.Broadcast(Constants.EventNames.MainHomeCameraSwip, { isTrue = false })
        local sceneManagement = SceneManagement:GetInstance()
        local sceneId = KCookie.Get(Constants.UICacheDataKeys.MainSceneID)
        ---@type SceneInstance
        local sceneInstance = sceneManagement:GetSceneInstance(sceneId)
        if sceneInstance == nil then
            return
        end
        Events.Broadcast(Constants.EventNames.MainHomeRoleActive, { isShow = false })
        -----@type UnityEngine.GameObject
        --local roleLocation      = sceneInstance:GetCacheObjectByName(CardProgressionConstants.SceneDefine.Cultivate_loc)
        --if roleLocation then
        --    KTool.SetActive(roleLocation.gameObject, false)
        --end
        coroutine.yield(CS.UnityEngine.WaitForSeconds(0.1))
        KTool.SetRenderFeatureActiveByName(Constants.RenderFeatureNames.BLUR, true)

        CfUtils.SetUICameraProjection(true)
        CfUtils.RefreshTopGoods({
            Constants.Currency.FreeDiamondId,
        })
        self.controller:StartCoroutine(util.cs_generator(function()
            while self.isStarting do
                --coroutine.yield(CoYield(3))
                while os.time() - self.startTime <= 3 do
                    coroutine.yield()
                end
                self.startTime = os.time()
                while self.isSwitching do
                    coroutine.yield()
                end
                if self.maxNo > 1 then
                    self.previewIndex = self.previewIndex - 1
                    if self.previewIndex < 1 then
                        self.previewIndex = self.maxNo
                    end
                    ---自动切下一个
                    self:OnSwitchNext()
                end
            end
        end))
    end))
    return coWait
end

function BeginnerEventDialog:OnHide()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local sceneManagement = SceneManagement:GetInstance()
        local sceneId = KCookie.Get(Constants.UICacheDataKeys.MainSceneID)
        ---@type SceneInstance
        local sceneInstance = sceneManagement:GetSceneInstance(sceneId)
        if sceneInstance == nil then
            return
        end

        ---@type UnityEngine.GameObject
        local roleLocation = sceneInstance:GetCacheObjectByName(CardProgressionConstants.SceneDefine.Cultivate_loc)
        if roleLocation then
            KTool.SetActive(roleLocation.gameObject, true)
        end
        KTool.SetRenderFeatureActiveByName(Constants.RenderFeatureNames.BLUR, false)
    end))
    return coWait
end

function BeginnerEventDialog:OnFocus(focus)
    KTool.SetActive(self.UIFX_BeginnerGiftBagPanel, focus)

    --有些界面跳转不会关掉自己这个界面
    if focus and self._isJump then
        self._isJump = false
        self:FillSelf()
    end
end

function BeginnerEventDialog:Awake()
    if isNull(self.TextTime.Env) then
        self.TextTime:Init()
    end
    self.BtnDayNodeLastDay = self.BtnDayNode.transform.parent:Find("BtnDaySevenNode")
    SetButtonAction(self.BtnClose, function()
        CfUtils.StartCoroutineWithBlocker(function()
            KTool.SetActive(self.controller, false)
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.2))
            UIModule.BackDialog()
        end)
    end)
    SetButtonAction(self.ClickArea, function()
        UIModule.BackDialog()
    end)
    SetButtonAction(self.BtnTitleGroup, function()
        self:GoToSelectReward()
    end)
    SetButtonAction(self.FontStyleButton, function()
        if self.drawnFinalPrize ~= 1 then
            KCookie.Set(NAME, ModuleType.Seven)
            self:GoToSelectReward()
        end
    end)
    self:FillSelf()
    self.__EventSdkEvent = Events.AddListener(Constants.EventNames.EVENT_SDK, Bind(self, self.OnEventSdkEvent))
end

function BeginnerEventDialog:FillSelf()
    GameUtils.Request(
            Interfaces.RookieHome,
            {},
            function(request, response)
                if checkInt(response.errCode) == 0 then
                    KTool.SetActive(self.LeftPanel, true)
                    self.checkinTimes = checkInt(response.data.checkinTimes)
                    self.nextCheckinLeftSeconds = checkInt(response.data.nextCheckinLeftSeconds)
                    self.todayNum = checkInt(response.data.todayNum)
                    self.sevenDaysTaskDojo = checkTable(response.data.tasks)
                    self.drawnFinalPrize = checkInt(response.data.drawnFinalPrize)
                    self.rookieQuestInfo = response.data.rookieQuestInfo
                    self.giftBagData = response.data.giftBag
                    self.loadingGraphs = checkTable(response.data.loadingGraphs)
                    self.isUseNewConfig = checkNumber(response.data.newTaskIsEnabled) == 1 --0旧表1新表
                    for k, v in pairs(self.giftBagData) do
                        v.id = (checkNumber(k) - 15000 + 1)
                    end
                    --数据获取完毕后开始处理相应事件
                    self.fortnightPrizeVo = self:GetFortnightPrizeVo()
                    self.sevenDaysTaskData = self:GetSevenDaysTaskData()--初步获取还未进行排序
                    --self.combatLevelsData = self:GetCombatData()
                    --self:FillLeftToggle()
                    self:StartLeftSecond()--开始倒计时
                    self:FreshSevenPanel()
                    local redPointCount = self:GetSevenDaysUnclaimedRewardCount()
                    GameUtils.SetRedPointNum(Constants.RedPointConst.SevenDays, redPointCount)
                    --self.FinalRewardGroup.Env:SetBtnCallBack(function()
                    --    self:GoToGetFortnightReward(self.FinalRewardGroup.gameObject, #self.fortnightPrizeVo)
                    --end)

                else
                    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
                        local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
                        playerComponent.playerDojo.rookieOpened = 0
                        coroutine.yield(CS.UnityEngine.WaitForSeconds(0.5))
                        UIModule.BackDialog()
                    end))
                    --UIModule.CloseDialog(self.controller, true)
                end
            end
    )
end

-- 支付成功的回调
function BeginnerEventDialog:OnEventSdkEvent(parameters)
    --- sdk pay succeed
    if parameters.event == Constants.EventNames.EVENT_SDK_PAY then
        local data = parameters.data
        if isNull(data) then
            return
        end
        local productId = checkInt(data.productId)
        if productId == 0 then
            return
        end

        local giftBagData = self.giftBagData
        local isHave = false
        for i, v in pairs(giftBagData) do
            if checkInt(v.productId) == productId then
                isHave = true
            end
        end
        if not isHave then
            return
        end

        self:LoadUIData(ModuleType.GiftBag)
    end

end

