function BeginnerEventDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local CriWareUtils = import('Game.Entry.CriWareUtilsFix')
        CriWareUtils.PlayRandomBGMFromCDList()
        ---@type CardProgressionControllerRole
        self.roleController_ = CardProgressionUtils.GetRoleControllerEnv()
