function BeginnerEventDialog:GoToGetFortnightReward(cell, day)
    local cellDay = checkInt(day)
    local available = self.nextCheckinLeftSeconds <= 0
    local isCanGet = available and cellDay == self.checkinTimes + 1

    if not isCanGet then
        local rewardData = self.fortnightPrizeVo[cellDay] --14日签到的最终大奖
        local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(rewardData.rewardId)
        if isTable(vo) then
            GameUtils.ShowCommonTipsBoard(cell, vo.name, vo.desc, vo.quality, vo.id)
        end
    else
        GameUtils.Request(
                Interfaces.RookieCheckin,
                {},
                function(request, response)
                    if checkInt(response.errCode) == 0 then
                        local data = response.data
                        GoodsUtils.DrawRewards(data.rewards)
                        UIModule.OpenDialog(
                                {
                                    id = Constants.UITypeIds.UICommonRewardPop,
                                    parameters = { rewards = data.rewards }
                                }
                        )
                        self:LoadUIData(ModuleType.Fortnight)
                    end
                end)
    end
end

function BeginnerEventDialog:FreshFortnightPanel()
    ---@region 累计14日大奖
    local finalDay = #self.fortnightPrizeVo
    local bigRewardData = self.fortnightPrizeVo[finalDay] --14日签到的最终大奖
    ---@type CommonBtnRoleNameNode
    local env = CfUtils.GetLuaScr(self.BtnRoleNameGroup, "Game.UI.Common.CommonBtnRoleNameNode")
    if env then
        env:RefreshSelf(bigRewardData.rewardId, 1, function()
            KCookie.Set(NAME, ModuleType.Fortnight)
        end, true)
    end
    --self.FinalRewardGroup.Env:RefreshStatue(self.nextCheckinLeftSeconds <= 0, self.checkinTimes, finalDay)


    KTool.SetActive(self.BtnRoleNameGroup, false)
    CoWait.Start():Coroutine(util.cs_generator(function()
        coroutine.yield(CS.UnityEngine.WaitForSeconds(0.5))
        KTool.SetActive(self.BtnRoleNameGroup, true)
        local env = CfUtils.GetLuaScr(self.BtnRoleNameGroup, "Game.UI.Common.CommonBtnRoleNameNode")
        if env then
            env:PlayAnimation("Go")
        end
    end))

    local cellW = 0
    local normalCount = #self.fortnightPrizeVo - 1
    for i = 1, normalCount do
        local go = self.fortnightNodeList[i]
        if not go then
            if i == 1 then
                go = self.RewardNode.gameObject
            else
                go = CfUtils.InstantiateGo(self.RewardNode.gameObject, self.ListViewDaily)
            end
            if go then
                go.name = "Node" .. i
                self.fortnightNodeList[i] = go.gameObject
            end
        end
        if cellW <= 0 then
            cellW = go.transform.rect.width
        end
        KTool.SetActive(go, true)
        local nodeEnv = CfUtils.GetLuaScr(go, "Game.UI.BeginnerEvent.BeginnerFortnightCellNode")
        if nodeEnv then
            local luaIndex = i
            local data = self.fortnightPrizeVo[luaIndex]
            nodeEnv:FreshBaseUI(data)
            nodeEnv:RefreshStatue(self.nextCheckinLeftSeconds <= 0, self.checkinTimes)
            nodeEnv:SetBtnCallBack(function()
                self:GoToGetFortnightReward(go.gameObject, luaIndex)
            end)
        end
    end

    CoWait.Start():Coroutine(util.cs_generator(function()
        coroutine.yield(Yielders.EndOfFrame)
        local layoutGroup = KTool.GetComponent(self.DailyContent.gameObject, typeof(CS.UnityEngine.UI.HorizontalLayoutGroup))
        local padding = layoutGroup.spacing
        self.DailyContent.localPosition = Vector3.New(-(cellW + padding) * self.checkinTimes, self.DailyContent.localPosition.y, self.DailyContent.localPosition.z)
        if self.nextCheckinLeftSeconds <= 0 then
            coroutine.yield(Yielders.EndOfFrame)
            if self.checkinTimes < normalCount then
                local go = self.fortnightNodeList[self.checkinTimes + 1]
                local nodeEnv = CfUtils.GetLuaScr(go, "Game.UI.BeginnerEvent.BeginnerFortnightCellNode")
                nodeEnv:PlayOpenAnim()
            elseif self.checkinTimes == normalCount then
                local go = self.FinalRewardGroup
                local nodeEnv = CfUtils.GetLuaScr(go, "Game.UI.BeginnerEvent.BeginnerFortnightCellNode")
                nodeEnv:PlayOpenAnim()
            end
        end
    end))
end

---刷新数据
---@param module integer @ ModuleType
function BeginnerEventDialog:LoadUIData(module)
    module = checkNumber(module)
    GameUtils.Request(
            Interfaces.RookieHome,
            {},
            function(request, response)
                if checkInt(response.errCode) == 0 then
                    if module == ModuleType.Fortnight then
                        self.checkinTimes = checkInt(response.data.checkinTimes)
                        self.nextCheckinLeftSeconds = checkInt(response.data.nextCheckinLeftSeconds)
                        self:FreshFortnightPanel()
                        local redPointCount = self.nextCheckinLeftSeconds > 0 and 0 or 1
                        GameUtils.SetRedPointNum(Constants.RedPointConst.Fortnight, redPointCount)
                    elseif module == ModuleType.Seven then
                        self.todayNum = checkInt(response.data.todayNum)
                        self.sevenDaysTaskDojo = checkTable(response.data.tasks)
                        self.drawnFinalPrize = checkInt(response.data.drawnFinalPrize)
                        self:FreshSevenPanel()
                        local redPointCount = self:GetSevenDaysUnclaimedRewardCount()
                        GameUtils.SetRedPointNum(Constants.RedPointConst.SevenDays, redPointCount)
                    elseif module == ModuleType.Combat then
                        self.rookieQuestInfo = response.data.rookieQuestInfo
                        self:FreshCombatPanel()
                        local redPointCount = self:GetCombatUnclaimedRewardCount()
                        GameUtils.SetRedPointNum(Constants.RedPointConst.Combat, redPointCount)
                    elseif module == ModuleType.GiftBag then
                        self.giftBagData = response.data.giftBag
                        local productToIds = {
                            ["15000"] = 1,
                            ["15001"] = 2,
                            ["15002"] = 3,
                            ["15003"] = 4,
                        }
                        for i, v in pairs(self.giftBagData) do
                            v.id = productToIds[tostring(v.productId)]  -- 指定资源id
                        end
                        self:FreshGiftBagPanel()
                        local redPointCount = self:GetGiftBagUnclaimedRewardCount()
                        GameUtils.SetRedPointNum(Constants.RedPointConst.GiftBag, redPointCount)
                    end
                end
            end
    )
end

function BeginnerEventDialog:GoToSelectReward()
    local isCompleted = self.sevenDaysTaskTotalityCount == self.sevenDaysTaskTotalityProgress--完成所有任务
    local isFinalPrizeDrawn = self.drawnFinalPrize == 1
    if isFinalPrizeDrawn then
        GameUtils.Toast(localize("奖励已领取"))
        return
    elseif not isCompleted then
        GameUtils.Toast(localize("为满足领取条件"))
        return
    end

    GameUtils.Request(Interfaces.RookieDrawFinalPrize, { prizeId = 1 }, function(request, response)
        if checkInt(response.errCode) == 0 then
            local data = response.data
            GoodsUtils.DrawRewards(data.rewards)
            UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = data.rewards } })
            self.drawnFinalPrize = 1
            self:FreshSevenPanel()
            ---@type PlayerComponent
            local playerComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
            if playerComponent then
                playerComponent.playerDojo.drawnFinalPrize = 1 ---已领取最张奖励
            end
            GameUtils.SetRedPointNum(Constants.RedPointConst.SevenDays, self:GetSevenDaysUnclaimedRewardCount())
        end
    end)



    --[[
    -- 这两个逻辑为修正使用镜头模糊后引发的一系列问题, 确保正确跳转以及镜头模糊正常显示
    self.keepBlur = true
    KCookie.Set(NAME, ModuleType.Seven)
    -- 这两个逻辑为修正使用镜头模糊后引发的一系列问题, 确保正确跳转以及镜头模糊正常显示

    UIModule.OpenDialog(
            {
                id = Constants.UITypeIds.RewardSelect,
                parameters = {
                    openType = (isCompleted and not isFinalPrizeDrawn) and 1 or 0,
                    isGet = self.drawnFinalPrize == 1,
                    --getCB = function ()
                    --    if isCompleted then
                    --        self:LoadUIData(ModuleType.Seven)
                    --    end
                    --end,
                    --jumpCB = function ()
                    --    KCookie.Set(NAME, ModuleType.Seven)
                    --end,
                },
            },
            {
                { id = Constants.UITypeIds.BeginnerEventDialog }
            }
    )
    ]]
end

function BeginnerEventDialog:FreshSevenPanel()
    if isNull(self.selectDayNum) then
        self.selectDayNum = math.min(self.todayNum, #self.sevenDaysTaskData)
    end
    if isNull(self.sevenOpenTime) then
        self.sevenOpenTime = CfUtils.GetAnimatorTime(self.TaskPanel, "UIBeginnerTaskPanel")
    end
    --if isNull(self.outAnimTime) then
    --    self.outAnimTime = CfUtils.GetAnimatorTime(self.ImgRole.transform, "BeginnerEventDialogTaskRoleChangeOut")
    --end
    self:ProcessingSevenDaysTaskDojo()
    ---@region 绘制左侧相关内容
    self:SlideShow()

    local isCompleted = self.sevenDaysTaskTotalityCount == self.sevenDaysTaskTotalityProgress--完成所有任务
    --print("==>>", isCompleted, self.sevenDaysTaskTotalityCount, self.sevenDaysTaskTotalityProgress)
    if isCompleted then
        local isFinalPrizeDrawn = self.drawnFinalPrize == 1
    else
        --if self.TextProgress then
        --    self.TextProgress.text = string.format("<color=#FFFFFF>%s</color>/%s", self.sevenDaysTaskTotalityProgress, self.sevenDaysTaskTotalityCount)
        --end
    end
    ---@endregion
    ---@region绘制右侧相关内容
    for i = 1, #self.sevenDaysTaskData do
        self:SortSevenDaysTaskData(i)
        local dayGo
        if isNull(self.dayGoEnvList[i]) then
            if i == #self.sevenDaysTaskData then
                dayGo = CfUtils.InstantiateGo(self.BtnDayNodeLastDay, self.LayoutDayGroup)
            else
                dayGo = CfUtils.InstantiateGo(self.BtnDayNode, self.LayoutDayGroup)
            end
            dayGo.name = "DayGo" .. i
            local dayGoEnv = CfUtils.GetLuaScr(dayGo, "Game.UI.BeginnerEvent.BeginnerSevenDayCellNode")
            self.dayGoEnvList[i] = dayGoEnv
        else
            dayGo = self.dayGoEnvList[i].controller.gameObject
        end
        self.dayGoEnvList[i]:UpdateRedPointStatus(self:IsDayTaskUnclaimed(i))
        local data = {
            progress = self.sevenDaysTaskProgress[i]["progress"],
            count = self.sevenDaysTaskProgress[i]["count"],
            day = i,
            isOpened = i <= self.todayNum
        }
        KTool.SetActive(dayGo, true)
        self.dayGoEnvList[i]:FreshBaseUI(data, self.todayNum, i == self.selectDayNum, #self.sevenDaysTaskData, isCompleted, self.drawnFinalPrize)
        self.dayGoEnvList[i]:SetBtnCallBack(function()
            if i ~= self.selectDayNum then
                if i <= self.todayNum then
                    if isCompleted and checkInt(self.drawnFinalPrize) == 0 then
                        ---任务全完成并且奖励未领取的情况下
                        GameUtils.Request(Interfaces.RookieDrawFinalPrize, { prizeId = 1 }, function(request, response)
                            if checkInt(response.errCode) == 0 then
                                local data = response.data
                                GoodsUtils.DrawRewards(data.rewards)
                                self.drawnFinalPrize = 1
                                ---@type PlayerComponent
                                local playerComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
                                if playerComponent then
                                    playerComponent.playerDojo.drawnFinalPrize = 1 ---已领取最张奖励
                                end
                                GameUtils.SetRedPointNum(Constants.RedPointConst.SevenDays, self:GetSevenDaysUnclaimedRewardCount())
                                GameUtils.InvokeRedPointCallBack(Constants.RedPointConst.SevenDays)
                                UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = data.rewards } })
                                self:FreshSevenPanel()
                            end
                        end)
                    else
                        self.dayGoEnvList[self.selectDayNum]:FreshSelectStatus(false)
                        self.selectDayNum = i
                        self.dayGoEnvList[self.selectDayNum]:FreshSelectStatus(true)
                        self:SetSevenContentCellNode(self.MainTaskCellGroup, self.sevenDaysTaskData[i][1])
                        if not self.ListViewTask.IsListViewInit then
                            self.ListViewTask:InitGridView(#self.sevenDaysTaskDataClone[i], Bind(self, self.OnGetItemByIndexSeven))
                        else
                            GameUtils.ReloadData(self.ListViewTask, #self.sevenDaysTaskDataClone[i])
                        end
                    end
                else
                    GameUtils.Toast(localize("还没有开放"))
                end
            elseif self.selectDayNum == #self.sevenDaysTaskData then
                local isFinalPrizeDrawn = checkInt(self.drawnFinalPrize) == 1
                if isFinalPrizeDrawn then
                    GameUtils.Toast(localize("奖励已领取"))
                    return
                elseif not isCompleted then
                    GameUtils.Toast(localize("为满足领取条件"))
                    return
                end
                ---最后一天情况
                GameUtils.Request(Interfaces.RookieDrawFinalPrize, { prizeId = 1 }, function(request, response)
                    if checkInt(response.errCode) == 0 then
                        local data = response.data
                        GoodsUtils.DrawRewards(data.rewards)
                        self.drawnFinalPrize = 1
                        ---@type PlayerComponent
                        local playerComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
                        if playerComponent then
                            playerComponent.playerDojo.drawnFinalPrize = 1 ---已领取最张奖励
                        end
                        GameUtils.SetRedPointNum(Constants.RedPointConst.SevenDays, self:GetSevenDaysUnclaimedRewardCount())
                        GameUtils.InvokeRedPointCallBack(Constants.RedPointConst.SevenDays)
                        UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = data.rewards } })
                        self:FreshSevenPanel()
                    end
                end)
            end
        end)
    end

    self.sevenDaysTaskDataClone = clone(self.sevenDaysTaskData)
    for i, v in pairs(self.sevenDaysTaskDataClone) do
        if (v[1].isMainTask) == 1 then
            table.remove(self.sevenDaysTaskDataClone[i], 1)
        end
    end

    if not self.ListViewTask.IsListViewInit then
        self.ListViewTask:InitGridView(#self.sevenDaysTaskDataClone[self.selectDayNum], Bind(self, self.OnGetItemByIndexSeven))
    else
        GameUtils.ReloadData(self.ListViewTask, #self.sevenDaysTaskDataClone[self.selectDayNum])
    end
    ---@endregion
    self:SetSevenContentCellNode(self.MainTaskCellGroup, self.sevenDaysTaskData[self.selectDayNum][1])
end

function BeginnerEventDialog:SetSevenContentCellNode(cell, data)
    local nodeEnv = CfUtils.GetLuaScr(cell.gameObject, "Game.UI.BeginnerEvent.BeginnerSevenContentCellNode")
    if nodeEnv then
        --local luaIndex = index + 1
        --local data = self.sevenDaysTaskData[self.selectDayNum][luaIndex]
        nodeEnv:FreshBaseUI(data)
        nodeEnv:SetBtnCallBackJump(function()
            local isCompleted = data.progress >= data.taskContentNum
            if not isCompleted then
                if checkNumber(data.openType) == 0 then
                    return
                end
                KCookie.Set(NAME, ModuleType.Seven)
                local goodsConfMgr = GoodsConfMgr:GetInstance()
                local row = goodsConfMgr:GetJumpModuleRow(data.openType)
                self._isJump = true
                goodsConfMgr:ExecuteJump(row, {})
            end
        end)
        nodeEnv:SetBtnCallBackGet(function()
            local isCompleted = data.progress >= data.taskContentNum
            local isDrawn = data.hasDrawn == 1
            if isCompleted and (not isDrawn) then
                GameUtils.Request(
                        Interfaces.RookieDrawTask,
                        { taskId = data.id },
                        function(request, response)
                            if checkInt(response.errCode) == 0 then
                                local data = response.data
                                local rewards = checkTable(data.rewards)
                                GoodsUtils.DrawRewards(rewards)
                                local targetId = 0
                                for _, v in pairs(rewards) do
                                    local goodsId = checkNumber(v.goodsId)
                                    if GoodsUtils.GetIdType(goodsId) == Constants.IDType.GoodsLoadingType then
                                        targetId = goodsId
                                        break
                                    end
                                end
                                if checkNumber(targetId) > 0 then
                                    print("===>>", targetId)
                                    if GoodsUtils.GetThingNo(targetId) <= 0 then
                                        return
                                    end
                                    ---@type GoodsLoadingVo
                                    local vo = CfUtils.GetCfVo(AutoIds.IdSetting6588, "GoodsLoadingVo", targetId)
                                    local cg = vo.cg
                                    CfUtils.DialogOpen(Constants.UITypeIds.CgPreviewDialog, {cg = cg, cb = function()
                                        UIModule.OpenDialog(
                                                {
                                                    id = Constants.UITypeIds.UICommonRewardPop,
                                                    parameters = { rewards = rewards }
                                                }
                                        )
                                    end})
                                else
                                    UIModule.OpenDialog(
                                            {
                                                id = Constants.UITypeIds.UICommonRewardPop,
                                                parameters = { rewards = rewards }
                                            }
                                    )
                                end
                                self:LoadUIData(ModuleType.Seven)
                            end
                        end
                )
            end
        end)
    end
end

