---七日任务左侧的角色立绘轮播
function BeginnerEventDialog:SlideShow()
    self:StopCo()
    self.isSwitching = false
    --色图轮播逻辑
    local todayNum = self.todayNum
    local t = {}
    for k, v in pairs(self.loadingGraphs) do
        if checkNumber(todayNum) >= checkNumber(k) then
            table.insert(t, checkNumber(v))
        end
    end
    self.loadingGraphs = t
    self.maxNo = #self.loadingGraphs
    --local tableFile = SettingMgr:GetInstance():Get(AutoIds.IdSetting6588)
    local id = self.loadingGraphs[self.previewIndex]
    --local tableRow = tableFile:GetByPrimaryKey(id)
    CfUtils.SetActive(self.ImgRole.transform:Find("ImgGot"), GoodsUtils.GetThingNo(id) > 0)
    --print(tableRow:Get("CG"))
    --print(tableRow:Get("thumbnail"))
    ---@type GoodsLoadingVo
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting6588, "GoodsLoadingVo", id)
    CfUtils.FillImage(self.ImgRole, vo.thumbnail)
    SetButtonAction(self.ImgRole, function()
        if self.previewIndex <= self.maxNo then
            local cid = self.loadingGraphs[self.previewIndex]
            if GoodsUtils.GetThingNo(cid) <= 0 then
                GameUtils.Toast(localize('完成右侧任务后解锁私密相片'))
                return
            end
            ---@type GoodsLoadingVo
            local vo = CfUtils.GetCfVo(AutoIds.IdSetting6588, "GoodsLoadingVo", cid)
            local cg = vo.cg
            print("===>>", cg)
            CfUtils.DialogOpen(Constants.UITypeIds.CgPreviewDialog, {cg = cg})
        end
    end)
    SetButtonAction(self.BtnPageL, function()
        self.previewIndex = self.previewIndex + 1
        if self.previewIndex > self.maxNo then
            self.previewIndex = 1
        end
        self.startTime = os.time()
        self:OnSwitchNext()
    end)
    SetButtonAction(self.BtnPageR, function()
        self.previewIndex = self.previewIndex - 1
        if self.previewIndex < 1 then
            self.previewIndex = self.maxNo
        end
        print("--->>", self.previewIndex)
        self.startTime = os.time()
        self:OnSwitchNext()
    end)
end

function BeginnerEventDialog:OnSwitchNext()
    if self.isSwitching then
        return
    end
    self.isSwitching = true
    if self.slideShowCo then
        cs_coroutine.stop(self.slideShowCo)
        self.slideShowCo = nil
    end
    self.slideShowCo = cs_coroutine.start(function()
        xTry(function()
            CfUtils.PlayAnimator(self.RoleNode, "BeginnerEventDialog_RoleNode_ChangeOut")
            coroutine.yield(Yielders.GetWaitForSeconds(0.3))
            local id = self.loadingGraphs[self.previewIndex]
            local tableFile = SettingMgr:GetInstance():Get(AutoIds.IdSetting6588)
            local tableRow = tableFile:GetByPrimaryKey(id)
            CfUtils.FillImage(self.ImgRole, parse_pathName(tableRow, "thumbnail"))
            CfUtils.SetActive(self.ImgRole.transform:Find("ImgGot"), GoodsUtils.GetThingNo(id) > 0)
            CfUtils.PlayAnimator(self.RoleNode, "BeginnerEventDialog_RoleNode_ChangeEntry")
            coroutine.yield(Yielders.GetWaitForSeconds(0.3))
            self.isSwitching = false
        end)
    end)
end

---将服务器返回的task数据的Id提出来作为Key
function BeginnerEventDialog:ProcessingSevenDaysTaskDojo()
    for k, v in pairs(self.sevenDaysTaskDojo) do
        self.sevenDaysTaskDojoProcessing[v.id] = v
    end
    self.sevenDaysTaskTotalityCount = 0
    self.sevenDaysTaskTotalityProgress = 0
    for key, value in ipairs(self.sevenDaysTaskData) do
        --处理实际用于使用的数据(配表与服务器融合)，并计算任务进度
        local dayTotalityCount = 0--总数
        local dayTotalityProgress = 0--完成度
        for i, b in ipairs(value) do
            local hasDrawn = self.sevenDaysTaskDojoProcessing[b.id].hasDrawn
            local progress = self.sevenDaysTaskDojoProcessing[b.id].progress
            self.sevenDaysTaskData[key][i]["hasDrawn"] = hasDrawn
            self.sevenDaysTaskData[key][i]["progress"] = checkInt(progress)
            --计算任务进度
            dayTotalityCount = dayTotalityCount + 1
            if checkNumber(hasDrawn) == 1 then
                dayTotalityProgress = dayTotalityProgress + 1
            end
            --
        end
        --计算任务进度
        self.sevenDaysTaskProgress[key] = {
            count = dayTotalityCount,
            progress = dayTotalityProgress,
        }
        self.sevenDaysTaskTotalityCount = self.sevenDaysTaskTotalityCount + dayTotalityCount
        self.sevenDaysTaskTotalityProgress = self.sevenDaysTaskTotalityProgress + dayTotalityProgress
        --
    end
end

---当天任务状态排序
function BeginnerEventDialog:SortSevenDaysTaskData(dayNum)
    table.sort(self.sevenDaysTaskData[dayNum], function(a, b)
        if a.isMainTask ~= b.isMainTask then
            return a.isMainTask > b.isMainTask
        elseif a.hasDrawn ~= b.hasDrawn then
            return a.hasDrawn < b.hasDrawn
        elseif a.progress / a.taskContentNum ~= b.progress / b.taskContentNum then
            return a.progress / a.taskContentNum > b.progress / b.taskContentNum
        elseif a.id ~= b.id then
            return a.id < b.id
        end
        return false
    end)
end

function BeginnerEventDialog:FreshCombatPanel()
    if not self.ListViewCombat.IsListViewInit then
        self.ListViewCombat:InitGridView(#self.combatLevelsData, Bind(self, self.OnGetItemByIndexCombat))
    else
        GameUtils.ReloadData(self.ListViewCombat, #self.combatLevelsData)
    end
    local cacheLevel = KCookie.Get("BeginnerEventDialogCombatLevel")
    if not isNull(cacheLevel) then
        local index = 0
        for i, v in pairs(self.combatLevelsData) do
            if checkNumber(v.id) == checkNumber(cacheLevel) then
                index = i - 1
            end
        end
        self.ListViewCombat:MovePanelToItemByRowColumn(index, 0)
        KCookie.Set("BeginnerEventDialogCombatLevel")
    end
end

function BeginnerEventDialog:OnGetItemByIndexCombat(listView, index)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem("TrainingCell")
    local nodeEnv = CfUtils.GetLuaScr(cell.gameObject, "Game.UI.BeginnerEvent.BeginnerCombatCellNode")
    if nodeEnv then
        if self.combatItemShowNum <= 0 then
            local cellSizeH = cell.CachedRectTransform.rect.height
            self.combatItemShowNum = math.ceil(listView.ViewPortHeight / cellSizeH)
        end
        if not self.combatAnimList[index + 1] and index <= self.combatItemShowNum then
            self.combatAnimList[index + 1] = true
            nodeEnv:PlayFadeInAnim(index)
        else
            nodeEnv:PlayInitAnim()
        end

        local luaIndex = index + 1
        local data = self.combatLevelsData[luaIndex]
        local taskStatus = self.rookieQuestInfo[checkString(self.combatLevelsData[luaIndex].id)]--(1:可领取 2:已领取)
        data["taskStatus"] = taskStatus
        nodeEnv:FreshBaseUI(data)
        nodeEnv:SetBtnCallBackGet(function()
            if taskStatus == 1 then
                GameUtils.Request(
                        Interfaces.RookieTrainReward,
                        { questId = data.id },
                        function(request, response)
                            if checkInt(response.errCode) == 0 then
                                --领奖界面
                                local responseData = response.data
                                GoodsUtils.DrawRewards(responseData.rewards)
                                UIModule.OpenDialog(
                                        {
                                            id = Constants.UITypeIds.UICommonRewardPop,
                                            parameters = { rewards = responseData.rewards }
                                        }
                                )
                                self:LoadUIData(ModuleType.Combat)
                            end
                        end
                )
            end
        end)
        nodeEnv:SetBtnCallBackFight(function()
            if taskStatus ~= 1 and taskStatus ~= 2 then
                local isUnlockMission = GameUtils.IsUnlocked(checkString(UNLOCK_TYPE), checkString(data.unlockMission)) --是否解锁,条件为通关主线
                if isUnlockMission then
                    KCookie.Set(NAME, ModuleType.Combat)
                    KCookie.Set("BeginnerEventDialogCombatLevel", data.id)
                    --UIModule.AddUIPage({id = Constants.UITypeIds.BeginnerEventDialog})
                    self.controller:SetExtraArgument(tostring(Constants.UITypeIds.BeginnerEventDialog))
                    fightPreWarMgr:FightEnter(data.id, { id = Constants.UITypeIds.BeginnerEventDialog })
                else
                    GameUtils.Toast(localize("请先") .. GameUtils.GetUnlockDescription(checkString(UNLOCK_TYPE), checkString(data.unlockMission)))
                end
            end
        end)
    end
    return cell
end

function BeginnerEventDialog:FreshGiftBagPanel()
    for k, v in pairs(self.giftBagData) do
        local giftBagEnv = CfUtils.GetLuaScr(self["GiftBagGroup" .. v.id], "Game.UI.BeginnerEvent.BeginnerGiftBagCell")
        if giftBagEnv then
