---进入界面开始倒计时
function BeginnerEventDialog:StartLeftSecond()
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local checkinServerTime = playerComponent.playerDojo.serverTime
    local checkinRookieTime = playerComponent.playerDojo.rookieOpened
    local nowTime = checkInt(TimeZoneUtils.UtcSeconds)
    local pastTime = nowTime - checkinServerTime
    local leftTime = checkinRookieTime - pastTime
    self.TextTime.Env:StartLeftSecond(leftTime, 3)
end

function BeginnerEventDialog:GetFortnightPrizeVo()

    local voList
    if self.isUseNewConfig then
        voList = CfUtils.GetWholeVo(AutoIds.IdSetting926, "FortnightPrizeVo")
    else
        voList = CfUtils.GetWholeVo(AutoIds.IdSetting922, "FortnightPrizeVo")
    end
    table.sort(voList, function(a, b)
        --按天数进行排序
        if a.day ~= b.day then
            return a.day < b.day
        end
    end)
    return voList
end

---将openDay提取出来作为key
function BeginnerEventDialog:GetSevenDaysTaskData()
    local settingMgr = SettingMgr:GetInstance()
    local idSetting = self.isUseNewConfig and AutoIds.IdSetting925 or AutoIds.IdSetting921
    local tableFile = settingMgr:Get(idSetting)
    local SevenDaysTaskVo = import('Game.Setting.Vo.SevenDaysTaskVo')
    local sevenDaysTaskVoList = {}
    for i, row in pairs(tableFile) do
        local vo = SevenDaysTaskVo.New()
        vo:FillVo(row)
        if sevenDaysTaskVoList[vo.openDay] then
            table.insert(sevenDaysTaskVoList[vo.openDay], vo)
        else
            sevenDaysTaskVoList[vo.openDay] = {}
            table.insert(sevenDaysTaskVoList[vo.openDay], vo)
        end

    end
    return sevenDaysTaskVoList
end

--获取战斗训练关卡表,将sortId提取出来作为key
function BeginnerEventDialog:GetCombatData()
    local voList = CfUtils.GetWholeVo(AutoIds.IdSetting924, "CombatLevelsVo")
    table.sort(voList, function(a, b)
        --按天数进行排序
        if a.sortId ~= b.sortId then
            return a.sortId < b.sortId
        end
    end)
    return voList
end

---红点改动，改成了未完成且未领取的数量2021-02-01-17-12
function BeginnerEventDialog:GetCombatUnclaimedRewardCount()
    local configRookieQuestInfoLineCount = 0--CfUtils.GetCf(AutoIds.IdSetting924, "CombatLevelsVo"):Count()
    local lockCount = 0
    local combatLevelsVo = CfUtils.GetWholeVo(AutoIds.IdSetting924, "CombatLevelsVo")
    for k, v in pairs(combatLevelsVo) do
        configRookieQuestInfoLineCount = configRookieQuestInfoLineCount + 1
        local isUnlockMission = GameUtils.IsUnlocked(checkString(UNLOCK_TYPE), checkString(v.unlockMission)) --是否解锁,条件为通关主线
        if not isUnlockMission then
            lockCount = lockCount + 1
        end
    end
    local hasGetCount = 0--已领取的数量
    for k, v in pairs(self.rookieQuestInfo) do
        if checkInt(v) == Constants.GetStatus.Has then
            hasGetCount = hasGetCount + 1
        end
    end
    return checkInt(configRookieQuestInfoLineCount - hasGetCount - lockCount)--（关卡总数 - 已领奖数 - 锁定数 = 未完成且未领取且未解锁数）
end

function BeginnerEventDialog:GetSevenDaysUnclaimedRewardCount()
    local count = 0
    for k, v in pairs(self.sevenDaysTaskData) do
        --一到七天
        if k <= self.todayNum then
            for i, b in pairs(v) do
                --每天的所有任务
                if b.progress >= b.taskContentNum then
                    if b.hasDrawn == 0 then
                        count = count + 1
                    end
                end
            end
        else
            break
        end
    end

    local isCompleted = self.sevenDaysTaskTotalityCount == self.sevenDaysTaskTotalityProgress--完成所有任务
    local isFinalPrizeDrawn = self.drawnFinalPrize == 1
    if isCompleted and not isFinalPrizeDrawn then
        count = count + 1
    end

    return count
end

function BeginnerEventDialog:GetGiftBagUnclaimedRewardCount()
    local count = 0
    for k, v in pairs(self.giftBagData) do
        --一到七天
        local consume = v.consume or {}
        if consume then
            if checkInt(v.giftType) == 1 and checkInt(v.consumeNum) == 0 and v.currentStock > 0 then
                count = count + 1
            end
        end
    end
    return count
end

---dayNum是否有未领取奖励
function BeginnerEventDialog:IsDayTaskUnclaimed(dayNum)
    local isUnclaimed = false
    for k, v in ipairs(self.sevenDaysTaskData[dayNum]) do
        if v.progress >= v.taskContentNum then
            if v.hasDrawn == 0 then
                if dayNum <= self.todayNum then
                    isUnclaimed = true
                    return isUnclaimed
                end
            end
        end
    end
    return isUnclaimed
end

function BeginnerEventDialog:StopCo()
    if self.slideShowCo then
        cs_coroutine.stop(self.slideShowCo)
        self.slideShowCo = nil
    end
end

function BeginnerEventDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.isStarting = false
        self.isSwitching = false
        if not self.keepBlur then
            KTool.SetRenderFeatureActiveByName(Constants.RenderFeatureNames.BLUR, false)
            Events.Broadcast(Constants.EventNames.MainHomeCameraSwip, { isTrue = true })
        end
        self:StopCo()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return BeginnerEventDialog